// Text edits that keep a hand-written YAML file as its author wrote it: comments, order, quoting and blank lines stay.
// Only top-level keys of a mapping are set here; anything deeper is renamed in place (src/migrate/keys.ts, moved.ts).

/** Is this file generated (its first line says "generated by"), so its importer writes it and migrate leaves it alone? */
export function generatedBy(text: string): string | undefined {
  const m = /generated by\s+(\S+)/.exec(text.split("\n", 1)[0] ?? "");
  return m ? m[1] : undefined;
}

const TOP = (key: string) => new RegExp(`^${key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*:(\\s|$)`);

/** The value written on a top-level key's own line ("" when it continues on the next lines), or undefined when absent. */
export function topValue(text: string, key: string): string | undefined {
  const line = text.split(/\r?\n/).find((l) => TOP(key).test(l));
  if (line === undefined) return undefined;
  return line.replace(TOP(key), "").replace(/\s+#.*$/, "").trim();
}

/**
 * Set a top-level key to a one-line value. An existing key keeps its line (and any trailing comment); a new one goes
 * after the first of `after` that the file has as a one-line key, else before the first top-level key.
 */
export function setTop(text: string, key: string, value: string, after: string[] = []): string {
  const eol = text.includes("\r\n") ? "\r\n" : "\n";
  const lines = text.split(/\r?\n/);
  const i = lines.findIndex((l) => TOP(key).test(l));
  if (i >= 0) {
    const comment = /\s+#.*$/.exec(lines[i].replace(TOP(key), ""))?.[0] ?? "";
    const line = `${key}: ${value}${comment}`;
    if (lines[i] === line) return text;
    // a value that continued on the next lines (a block) is replaced whole
    let j = i + 1;
    if (!lines[i].replace(TOP(key), "").replace(/\s+#.*$/, "").trim() || /^[|>]/.test(lines[i].replace(TOP(key), "").trim()))
      while (j < lines.length && (lines[j].trim() === "" || /^\s/.test(lines[j]))) j++;
    lines.splice(i, j - i, line);
    return lines.join(eol);
  }
  let at = -1;
  for (const k of after) {
    const a = lines.findIndex((l) => TOP(k).test(l) && l.replace(TOP(k), "").replace(/\s+#.*$/, "").trim() !== "" && !/^[|>]/.test(l.replace(TOP(k), "").trim()));
    if (a >= 0) { at = a + 1; break; }
  }
  if (at < 0) { at = lines.findIndex((l) => /^[A-Za-z_"'][^:]*:(\s|$)/.test(l)); if (at < 0) at = lines.length; }
  lines.splice(at, 0, `${key}: ${value}`);
  return lines.join(eol);
}

/** A line-by-line difference of two texts, for --dry-run: changed lines as "-" and "+" with their line numbers. */
export function lineDiff(file: string, before: string | undefined, after: string): string[] {
  if (before === undefined) return [`+++ ${file} (new)`, ...after.replace(/\n$/, "").split("\n").map((l) => `+ ${l}`)];
  const a = before.split("\n"), b = after.split("\n");
  const out = [`--- ${file}`];
  // a small longest-common-subsequence diff: these files are short and the edits are few
  const n = a.length, m = b.length;
  const L: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) L[i][j] = a[i] === b[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1]);
  let i = 0, j = 0;
  while (i < n || j < m) {
    if (i < n && j < m && a[i] === b[j]) { i++; j++; }
    else if (j < m && (i >= n || L[i][j + 1] >= L[i + 1][j])) { out.push(`+ ${j + 1}: ${b[j]}`); j++; }
    else { out.push(`- ${i + 1}: ${a[i]}`); i++; }
  }
  return out;
}
